import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.batches.create({ input_file_id: "string", endpoint: "/v1/responses", completion_window: "24h", metadata: { key: "string" }, output_expires_after: { anchor: "created_at", seconds: 1 } });
console.log(result);
